import{_ as d,C as a,o as i,c as p,E as n,a3 as l,w as h,j as t,a as s}from"./chunks/framework.CCylkYel.js";const c="/screens/devices/step-seq.png",g="/screens/devices/step-seq-hold.png",u="/screens/devices/step-seq-step.png",m="/screens/devices/step-seq-step-options.png",S="/screens/devices/step-seq-settings.png",A=JSON.parse('{"title":"Step Seq","description":"","frontmatter":{"title":"Step Seq","pageClass":"device-doc"},"headers":[],"relativePath":"devices/step-seq.md","filePath":"devices/step-seq.md"}'),b={name:"devices/step-seq.md"};function f(v,e,q,E,N,P){const r=a("DeviceHeading"),o=a("ManualRelated");return i(),p("div",null,[n(r,{slug:"step-seq",title:"Step Seq"}),e[1]||(e[1]=l('<p>Classic clock-synced step sequencer</p><p><img src="'+c+'" alt="Step Seq: a 16-step C minor bassline with three rests, step 5 playing." class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Write a bassline or a riff that loops in time, no keyboard needed. Each of up to 16 steps has its own note, velocity and length.</p><p>A new Step Seq has every step off: turn on the steps you want to hear.</p><p><strong>BYPASS</strong> keeps the sequence in time: turn it off mid-bar and it comes back in on the step it would be playing, not on step 1.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Put a <a href="/devices/clock">Clock</a> before it in the rack. Without one it doesn&#39;t play.</p></div><h2 id="editing-steps" tabindex="-1">Editing steps <a class="header-anchor" href="#editing-steps" aria-label="Permalink to &quot;Editing steps&quot;">​</a></h2><p>Step Seq opens on the <strong>SEQ</strong> tab: a grid of up to 16 pads, one per step. <strong>Select + Back</strong> switches to the pencil tab with the device settings.</p><table tabindex="0"><thead><tr><th>Control</th><th>On a step</th></tr></thead><tbody><tr><td><strong>Select</strong></td><td>Turns the step on or off</td></tr><tr><td>Hold <strong>Select</strong> and turn</td><td>Changes the step&#39;s note</td></tr><tr><td>Hold <strong>Select</strong> without turning</td><td>Opens the <strong>STEP</strong> panel</td></tr></tbody></table><p><img src="'+g+'" alt="Step Seq: hold Select and turn to change the note" class="screen"></p><h3 id="step-panel" tabindex="-1">STEP panel <a class="header-anchor" href="#step-panel" aria-label="Permalink to &quot;STEP panel&quot;">​</a></h3><p>Every step has its own settings, and each one can have its own <strong>MODULATION</strong> and <strong>MAPPING</strong>. Rows edit like any value: see <a href="./../navigation/controls#edit-a-value">Edit a value</a>. <strong>Back</strong> closes the panel.</p><p><img src="'+u+'" alt="STEP 3: G1 at velocity 80, full gate." class="screen"></p><p><img src="'+m+'" alt="Step Seq: MODULATION and MAPPING from a STEP row" class="screen"></p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>BYPASS</td><td>OFF / ON</td><td>ON: MIDI passes through and the sequence keeps its place in silence. OFF: it comes back in time. See <a href="/devices/#bypass">BYPASS</a>.</td></tr><tr><td>STEPS</td><td>4 – 16</td><td>Length of the pattern in steps.</td></tr><tr><td>RATE</td><td>1/1 – 1/64</td><td>Length of each step.</td></tr><tr><td>SEQ CH</td><td>GLOBAL – CH16</td><td>Channel for steps whose <strong>CHANNEL</strong> is <strong>GLOBAL</strong>. <strong>GLOBAL</strong> follows the <a href="/projects/#channel">project&#39;s channel</a>.</td></tr><tr><td>DIRECTION</td><td>FWD – PINGPONG</td><td>Which way the playhead moves.</td></tr><tr><td>RANDOMIZE</td><td>—</td><td>Tap <strong>Select</strong> to rewrite steps at random. See below.</td></tr><tr><td>RAND DEPTH</td><td>0% – 100%</td><td>Share of the steps <strong>RANDOMIZE</strong> rewrites.</td></tr></tbody></table></div><p><img src="'+S+'" alt="Step Seq settings: 16 steps at 1/16." class="screen"></p><h2 id="step-parameters" tabindex="-1">Step parameters <a class="header-anchor" href="#step-parameters" aria-label="Permalink to &quot;Step parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>ACTIVE</td><td>OFF / ON</td><td>ON: the step plays.</td></tr><tr><td>NOTE</td><td>C-2 – G8</td><td>Note of the step.</td></tr><tr><td>VELOCITY</td><td>1 – 127</td><td>Velocity of the step.</td></tr><tr><td>GATE</td><td>10% – 200%</td><td>Note length as a share of the step.</td></tr><tr><td>CHANNEL</td><td>GLOBAL – CH16</td><td>Channel of the step. <strong>GLOBAL</strong> uses <strong>SEQ CH</strong>.</td></tr><tr><td>PROBABILITY</td><td>0% – 100%</td><td>Chance that the step plays.</td></tr></tbody></table><h2 id="parameter-values" tabindex="-1">Parameter values <a class="header-anchor" href="#parameter-values" aria-label="Permalink to &quot;Parameter values&quot;">​</a></h2><h3 id="randomize" tabindex="-1">RANDOMIZE <a class="header-anchor" href="#randomize" aria-label="Permalink to &quot;RANDOMIZE&quot;">​</a></h3><p>Tap <strong>Select</strong> on <strong>RANDOMIZE</strong>. Each step is rewritten with a chance of <strong>RAND DEPTH</strong>: a new note between C1 and B4, a new velocity, gate and probability. <strong>ACTIVE</strong> and <strong>CHANNEL</strong> stay as they are.</p>',23)),n(o,null,{default:h(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"/racks/"},"Racks"),s(" — build a chain of devices")]),t("li",null,[t("a",{href:"/concepts/mapping"},"Mapping"),s(" — put a device setting on a knob or an LFO")]),t("li",null,[t("a",{href:"/concepts/modulation"},"Modulation"),s(" — move a setting while you play")])],-1)])]),_:1})])}const O=d(b,[["render",f]]);export{A as __pageData,O as default};
